import{_ as s,c as n,o as a,a0 as t}from"./chunks/framework.oTSD2LDJ.js";const k=JSON.parse('{"title":"CppExt Backend Overview","description":"","frontmatter":{"title":"CppExt Backend Overview","editLink":true},"headers":[],"relativePath":"en/controls-reference/cpp-ext/overview.md","filePath":"en/controls-reference/cpp-ext/overview.md"}'),i={name:"en/controls-reference/cpp-ext/overview.md"};function p(l,e,o,r,d,c){return a(),n("div",null,e[0]||(e[0]=[t(`<h1 id="cppext-backend-overview" tabindex="-1">CppExt Backend Overview <a class="header-anchor" href="#cppext-backend-overview" aria-label="Permalink to &quot;CppExt Backend Overview&quot;">​</a></h1><p>The <code>CppExt</code> folder contains all C++-based backend singletons and utility classes used by Uniquenium. These classes are registered into the QML type system via <code>QML_SINGLETON</code> and can be accessed directly in QML by their type name without instantiation.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  Uniquenium App                      │</span></span>
<span class="line"><span>│  main.qml  ───  Creates UniDeskComManager instance   │</span></span>
<span class="line"><span>└────────────┬────────────────────────────────────────┘</span></span>
<span class="line"><span>             │ passes comManager property</span></span>
<span class="line"><span>             ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  UniDesk Controls / Components (QML)                │</span></span>
<span class="line"><span>│  ├─ UniDeskWindow / UniDeskButton / UDCText ...    │</span></span>
<span class="line"><span>│  └─ Accesses services via comManager                │</span></span>
<span class="line"><span>└────────────┬────────────────────────────────────────┘</span></span>
<span class="line"><span>             │ import UniDesk 1.0</span></span>
<span class="line"><span>             ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  CppExt C++ Singleton Layer                          │</span></span>
<span class="line"><span>│  ├─ UniDeskGlobals      Global theme state          │</span></span>
<span class="line"><span>│  ├─ UniDeskSettings     User settings persistence   │</span></span>
<span class="line"><span>│  ├─ UniDeskTools        General utility functions   │</span></span>
<span class="line"><span>│  ├─ UniDeskExpr         Expression engine          │</span></span>
<span class="line"><span>│  ├─ UniDeskSystemInfo   System information         │</span></span>
<span class="line"><span>│  ├─ UniDeskPluginMgr    Plugin loading/management   │</span></span>
<span class="line"><span>│  ├─ UniDeskTempleteMgr  Template import/export      │</span></span>
<span class="line"><span>│  ├─ UniDeskComponentsData Component data persistence│</span></span>
<span class="line"><span>│  └─ ...                                             │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><p>All CppExt singletons are registered via <code>QML_SINGLETON</code> + <code>QML_NAMED_ELEMENT</code>. After <code>import UniDesk 1.0</code>, they can be accessed directly:</p><div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> UniDesk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Read system theme</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.log(&quot;Theme:&quot;, UniDeskGlobals.isLight ? &quot;Light&quot; : &quot;Dark&quot;)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Get CPU usage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var stats = UniDeskSystemInfo.getSystemStats()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.log(&quot;CPU:&quot;, stats.cpu.usagePercent, &quot;%&quot;)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Evaluate expression</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">var text = UniDeskExpr.convertStr(&quot;Current CPU: %{cpu}%&quot;)</span></span></code></pre></div><h2 id="relationship-with-unideskcommanager" tabindex="-1">Relationship with UniDeskComManager <a class="header-anchor" href="#relationship-with-unideskcommanager" aria-label="Permalink to &quot;Relationship with UniDeskComManager&quot;">​</a></h2><p>CppExt singletons are responsible for low-level data and native features, while <code>UniDeskComManager</code> (a QML control) is responsible for organizing components and pages at a higher level:</p><ul><li><code>UniDeskComManager</code> calls methods on <code>UniDeskComponentsData</code> for persistence when creating/saving/loading components</li><li>Template import/export is handled by <code>UniDeskTempleteMgr</code>, which signals <code>UniDeskComManager</code> to rebuild components</li><li>After plugins are loaded by <code>UniDeskPluginMgr</code>, the newly registered types are merged into <code>UniDeskComManager.type_list</code></li></ul><h2 id="documentation-index" tabindex="-1">Documentation Index <a class="header-anchor" href="#documentation-index" aria-label="Permalink to &quot;Documentation Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Category</th><th>Description</th></tr></thead><tbody><tr><td><a href="./UniDeskGlobals">UniDeskGlobals</a></td><td>Global State</td><td>Theme mode, app quit signal, i18n</td></tr><tr><td><a href="./UniDeskSettings">UniDeskSettings</a></td><td>Global State</td><td>User settings read/write</td></tr><tr><td><a href="./UniDeskTools">UniDeskTools</a></td><td>Utilities</td><td>Colors, system commands, fonts, wallpapers, UUID, auto-start</td></tr><tr><td><a href="./UniDeskExpr">UniDeskExpr</a></td><td>Expression Engine</td><td><code>%{value}</code> evaluation, API response parsing</td></tr><tr><td><a href="./UniDeskSystemInfo">UniDeskSystemInfo</a></td><td>System Info</td><td>CPU, memory, network, battery real-time data</td></tr><tr><td><a href="./UniDeskPluginMgr">UniDeskPluginMgr</a></td><td>Plugin Manager</td><td>DLL plugin load, unload, type registration</td></tr><tr><td><a href="./UniDeskTempleteMgr">UniDeskTempleteMgr</a></td><td>Template System</td><td>Template save, load, list refresh, media handling</td></tr><tr><td><a href="./UniDeskComponentsData">UniDeskComponentsData</a></td><td>Data Persistence</td><td>Page/component JSON read/write</td></tr><tr><td><a href="./UniDeskPluginInterface">UniDeskPluginInterface</a></td><td>Plugin Interface</td><td>Abstract base class for C++ plugins</td></tr></tbody></table>`,12)]))}const g=s(i,[["render",p]]);export{k as __pageData,g as default};
